<?php require __DIR__.'/includes/bootstrap.php'; $title='Contact';$error='';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$subject=trim($_POST['subject']??'');$body=trim($_POST['message']??'');if(!$pdo)$error='Contact service is temporarily unavailable.';elseif($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$subject===''||$body==='')$error='Please complete all fields with a valid email address.';elseif(strlen($body)>10000)$error='Message is too long.';else{$s=$pdo->prepare('INSERT INTO contact_messages(name,email,subject,message) VALUES(?,?,?,?)');$s->execute([$name,$email,$subject,$body]);$message='Your message has been sent.';}}require __DIR__.'/includes/header.php';?><div class="container"><section class="card" style="max-width:700px;margin-inline:auto"><h1>Contact</h1><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><?php if($message):?><p role="status"><?=e($message)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><label>Name<input name="name" required maxlength="120"></label></p><p><label>Email<input type="email" name="email" required maxlength="190"></label></p><p><label>Subject<input name="subject" required maxlength="255"></label></p><p><label>Message<textarea name="message" rows="8" required maxlength="10000"></textarea></label></p><button>Send message</button></form></section></div><?php require __DIR__.'/includes/footer.php';
